<?php
/** Context-aware browser back/forward-cache header analysis. @package NakhostinPerformanceEngine */
namespace Nakhostin\PerformanceEngine\Diagnostics;
final class BFCacheAnalyzer { public function analyze( array $headers, string $context = 'public' ): array { $cache = strtolower( (string) ( $headers['cache-control'] ?? $headers['Cache-Control'] ?? '' ) ); $pragma = strtolower( (string) ( $headers['pragma'] ?? $headers['Pragma'] ?? '' ) ); $blocking = false !== strpos( $cache, 'no-store' ) || false !== strpos( $cache, 'private' ) || false !== strpos( $pragma, 'no-cache' ); $private = in_array( $context, array( 'cart', 'checkout', 'account', 'admin', 'logged_in' ), true ); return array( 'status' => $blocking ? ( $private ? 'expected' : 'investigate' ) : 'healthy', 'blocking_headers' => $blocking, 'private_context' => $private, 'recommendation' => $blocking && ! $private ? 'Identify the component adding private or no-store headers to this public page.' : '' ); } }
